descriptor.templateCss:
.tripguard-control,.tg-control{font-family:"OpenAI Sans", ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif}
.tg-control{
  height:100%;box-sizing:border-box;padding:16px;background:#fff;
  border:1px solid #e5e7eb;border-radius:14px;overflow:auto;color:#111827
}
.tg-control-head{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;margin-bottom:14px}
.tg-control-title{font-size:18px;line-height:1.25;font-weight:650;letter-spacing:-.01em}
.tg-control-sub{margin-top:3px;font-size:12px;line-height:1.4;color:#6b7280}
.tg-status{max-width:46%;padding:6px 9px;border-radius:999px;background:#f3f4f6;color:#4b5563;font-size:11px;font-weight:600;text-align:center}
.tg-status.sending{background:#fffbeb;color:#92400e}
.tg-status.success{background:#ecfdf5;color:#047857}
.tg-status.error{background:#fef2f2;color:#b42318}
.tg-primary-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}
.tg-btn{
  min-height:42px;border-radius:10px;padding:9px 12px;font-family:inherit;
  font-size:12.5px;font-weight:600;cursor:pointer;transition:background .15s ease,border-color .15s ease,transform .05s ease
}
.tg-btn:active{transform:translateY(1px)}
.tg-btn:disabled,.tg-period button:disabled{opacity:.45;cursor:not-allowed}
.tg-btn.primary{border:1px solid #111827;background:#111827;color:#fff}
.tg-btn.secondary{border:1px solid #d1d5db;background:#fff;color:#111827}
.tg-btn.secondary:hover,.tg-btn.ghost:hover{background:#f9fafb}
.tg-btn.danger{border:1px solid #dc2626;background:#dc2626;color:#fff}
.tg-sos-remote{width:100%;margin-top:8px}
.tg-advanced{margin-top:12px;border-top:1px solid #eceff3;padding-top:10px}
.tg-advanced summary{cursor:pointer;color:#4b5563;font-size:12px;font-weight:600;user-select:none}
.tg-advanced-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px;margin-top:10px}
.tg-btn.ghost{border:1px solid #e5e7eb;background:#f9fafb;color:#374151}
.tg-period{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-top:10px;padding-top:10px;border-top:1px solid #f0f2f5;font-size:12px;color:#6b7280}
.tg-period-actions{display:flex;gap:6px}
.tg-period button{border:1px solid #d1d5db;background:#fff;color:#374151;border-radius:8px;padding:6px 10px;font:600 11px "OpenAI Sans", ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;cursor:pointer}
@media(max-width:650px){
  .tg-control{padding:12px}
  .tg-control-head{flex-direction:column}
  .tg-status{max-width:100%}
  .tg-primary-grid,.tg-advanced-grid{grid-template-columns:1fr}
  .tg-btn{min-height:44px}
}

descriptor.controllerScript:
self.onInit = function() {
  var scope = self.ctx.$scope;
  scope.busy = false;
  scope.status = 'Sẵn sàng nhận lệnh';
  scope.statusClass = 'ready';

  function updateStatus(text, cssClass) {
    scope.status = text;
    scope.statusClass = cssClass;
    if (scope.$evalAsync) { scope.$evalAsync(); }
  }

  scope.sendTripGuardCommand = function(method, params, confirmation) {
    if (scope.busy) { return; }
    if (confirmation && !window.confirm(confirmation)) { return; }

    scope.busy = true;
    updateStatus('Đang gửi: ' + method + ' ...', 'sending');

    var timeout = Number(self.ctx.settings.requestTimeout || 15000);
    var finished = false;
    var watchdog;

    function finishOk() {
      if (finished) { return; }
      finished = true;
      window.clearTimeout(watchdog);
      scope.busy = false;
      updateStatus('Đã chuyển lệnh: ' + method + '. Xem kết quả lệnh bên dưới.', 'success');
    }

    function finishError(error) {
      if (finished) { return; }
      finished = true;
      window.clearTimeout(watchdog);
      scope.busy = false;
      var code = error && error.status ? ' (' + error.status + ')' : '';
      updateStatus('Không gửi được ' + method + code, 'error');
    }

    watchdog = window.setTimeout(function() {
      finishError({ status: 'timeout' });
    }, timeout + 1000);

    try {
      self.ctx.controlApi.sendOneWayCommand(method, params, timeout)
        .subscribe(finishOk, finishError, finishOk);
    } catch (error) {
      finishError(error);
    }
  };
};

self.typeParameters = function() {
  return {
    maxDatasources: 0,
    dataKeysOptional: true,
    singleEntity: true,
    previewWidth: '760px',
    previewHeight: '360px'
  };
};

self.onDestroy = function() {};
